#include <iostream>
using namespace std;

class PaymentProcessor {
public:
    virtual void process(double amount) = 0; // no body: just the WHAT
    virtual ~PaymentProcessor() {}
};

class CardPayment : public PaymentProcessor {
public:
    void process(double amount) override {
        cout << "Processing $" << amount << " via card" << endl;
    }
};

int main() {
    PaymentProcessor* processor = new CardPayment();
    processor->process(100);
    delete processor;
    return 0;
}

