interface PaymentProcessor {
    void process(double amount); // WHAT every processor can do, not HOW
}

// Hidden complexity lives inside each implementation, not in the interface
class CreditCardPayment implements PaymentProcessor {
    @Override
    public void process(double amount) {
        // card validation, bank network calls, fraud checks all hidden here
        System.out.println("Processing $" + amount + " via Credit Card");
    }
}

class UpiPayment implements PaymentProcessor {
    @Override
    public void process(double amount) {
        // UPI handle resolution, bank server round-trip all hidden here
        System.out.println("Processing $" + amount + " via UPI");
    }
}

public class Main {
    // This method knows NOTHING about CreditCardPayment or UpiPayment specifically
    static void checkout(PaymentProcessor processor, double amount) {
        processor.process(amount);
    }

    public static void main(String[] args) {
        PaymentProcessor processor1 = new CreditCardPayment(); // client only knows the interface
        PaymentProcessor processor2 = new UpiPayment();

        checkout(processor1, 250.0);
        checkout(processor2, 99.0);
    }
}

