#include <iostream>
using namespace std;

class PaymentProcessor {
public:
    virtual void process(double amount) = 0; // pure virtual: WHAT, not HOW
    virtual ~PaymentProcessor() {}
};

// Hidden complexity lives inside each implementation, not in the interface
class CreditCardPayment : public PaymentProcessor {
public:
    void process(double amount) override {
        // card validation, bank network calls, fraud checks all hidden here
        cout << "Processing $" << amount << " via Credit Card" << endl;
    }
};

class UpiPayment : public PaymentProcessor {
public:
    void process(double amount) override {
        // UPI handle resolution, bank server round-trip all hidden here
        cout << "Processing $" << amount << " via UPI" << endl;
    }
};

// This function knows NOTHING about CreditCardPayment or UpiPayment specifically
void checkout(PaymentProcessor* processor, double amount) {
    processor->process(amount);
}

int main() {
    PaymentProcessor* processor1 = new CreditCardPayment(); // client only knows the interface
    PaymentProcessor* processor2 = new UpiPayment();

    checkout(processor1, 250.0);
    checkout(processor2, 99.0);

    delete processor1;
    delete processor2;
    return 0;
}
